FIXES = [('Supplementary Figure S2', 'Supplemental Figure S4'), ('Supplementary Figure S3', 'Supplemental Figure S7'), ('Supplementary Figure S1', 'Supplemental Figure S6'), ('main Table 3', 'Supplemental Table S38'), ('Supplementary', 'Supplemental'), ('supplementary', 'supplemental')]

def fix(s):
    for a, b in FIXES:
        s = s.replace(a, b)
    return s

def refix(blocks):
    out = []
    for b in blocks:
        if b[0] in ('p', 'h1', 'h2'):
            out.append((b[0], fix(b[1])))
        elif b[0] == 'table':
            t = dict(b[1])
            t['title'] = fix(t['title'])
            t['note'] = fix(t.get('note', ''))
            t['rows'] = [[fix(c) if isinstance(c, str) else c for c in r] for r in t['rows']]
            out.append(('table', t))
        else:
            out.append(b)
    return out

def sha_pre(path, marker=b'\n## Addendum'):
    b = path.read_bytes()
    return hashlib.sha256(b.split(marker)[0]).hexdigest().upper()

