    for i, src in srcs.items():
        Image.open(src).convert('RGB').save(OUT / f'figure_s{i}.png', dpi=(300, 300))
    L = M.legends()
    lg = lambda i, j: fix(L[i]).replace(f'Figure {j}.', f'Figure S{srcs_idx[j]}.', 1)
    srcs_idx = {1: 1, 4: 2, 5: 3, 7: 4, 2: 8, 6: 9}
    e10_legend = f"Figure S5. The 2026 guideline's 30-year-risk statin pathway (post hoc). A, Probability that the base PREVENT 30-year ASCVD classification (≥10% vs <10%) differed at the second examination, by first-examination 30-year risk, among {XA['n_A1']} participants aged 30–59 years not taking a statin (restricted cubic spline logistic regression on the logit distance from 10%; pointwise 95% cluster-bootstrap intervals; diamonds, observed proportions as changes/participants); shading marks the zones where the probability is ≥25% and ≥10%. B, The same for the LDL-C ≥160 mg/dL classification (Sampson LDL-C). C, Status at the second examination of the {XE['n']} participants who qualified through the pathway at the first. D, Survey-weighted distribution of 30-year risk among US adults aged 30–59 years in the pathway domain, NHANES 2021–2023 fasting subsample (complete-case totals); teal, 30-year risk ≥10%; shading, the ≥25% zone from A. Probabilities condition on the first examination and include regression to the mean; the projection assumes 1988–1994 within-person variation."
    s1_legend = 'Figure S6. Sensitivity analyses. A, base PREVENT-ASCVD θ under each sensitivity analysis and alternative interval methods for the primary estimate (SA15); B, θ_U under the analyses run for the UACR model. Shaded band: ±1.5 pp around each primary estimate; for θ this is the prespecified abstract-reporting threshold for key analyses, and in B it is shown for reference only. Intervals are CR1 logit-t 95% CIs (SA10: cluster bootstrap with refitted weights).'
    s7_legend = 'Figure S7. Study 2: where category changes occur (post hoc; NHANES 2009–2010, n = 3,166). a, UACR pairs on log axes colored by PREVENT-UACR category change with first-morning urine (unweighted points); dashed lines mark 30 mg/g and the shaded region holds pairs below 30 mg/g in both specimens. b, such pairs form 91.89% of the weighted cohort and 78.46% of its weighted category changes. c, three fixed first-specimen selection scenarios ("near risk boundary": within an inclusive 0.5 pp of 3%, 5% or 10%), with denominators of the whole cohort, all category changes and the selected participants; points are weighted percentages with 95% intervals. d, fasting subset (n = 1,053; LDL cholesterol 70–189 mg/dL, no diabetes or statin use; fasting-subsample weights): left, downward and upward crossing frequencies with unweighted counts; right, paired net change in the fraction at or above each threshold with 95% intervals. These describe risk-label changes, not prescribing changes. Panel b shows two decimals as produced in the Study 2 analysis (Supplemental Tables S21–S23).'
    figs = [('h1', 'Supplemental Figures')]
    s9_legend = lg(5, 6).replace('Figure S9.', 'Figure S9. Study 2 displays and the earlier combined ladder (superseded in the main text by Figure 3, which separates the designs).', 1)
    for i, leg in [(1, lg(0, 1)), (2, lg(3, 4)), (3, lg(4, 5)), (4, lg(6, 7)), (5, e10_legend), (6, s1_legend), (7, s7_legend), (8, lg(1, 2)), (9, s9_legend)]:
        figs += [('figure', OUT / f'figure_s{i}.png', leg, 6.0), ('break',)]
    blocks = [('title', 'Supplemental Material'), ('p', M7.TITLE), ('p', 'Yunhao Jiang'), ('p', 'Contents: Supplemental Methods (Study 1; Study 2; post hoc sets; audits; review-prompted analyses); Supplemental Tables S1–S41; Supplemental Figures S1–S9; Supplemental References. The frozen Study 1 protocol and the dated post hoc protocols with their addenda are provided as separate supplemental files. Main-text figure and table numbers refer to revision 7, draft 2 (Figures 1–4, Tables 1–2).')] + refix(SUP.methods()) + refix(SUP.methods2()) + methods3() + methods4() + [('break',), ('h1', 'Supplemental Tables: Study 1 (NHANES III)')] + refix(SUP.tables()) + [('p', ''), ('h1', 'Supplemental Tables: Study 2 (NHANES 2009–2010 and 2001–2002)')] + refix(SUP.tables2()) + [('p', ''), ('h1', 'Supplemental Tables: post hoc additions')] + patch_s32(refix(SUP.tables3())) + [('p', '')] + tables4() + [('p', '')] + tables5() + [('break',)] + figs[:-1]
    order = W.number_citations(blocks)
    refs = [M7.ref_text(k) for k in sorted(order, key=order.get)]
    doc = W.new_doc('Supplemental Material: ' + M7.TITLE)
    for sec in doc.sections:
        sec.left_margin = sec.right_margin = W.Inches(0.7)
    doc.styles['Normal'].paragraph_format.line_spacing = 1.15
    W.render(doc, blocks, order, prefix='S')
    W.para(doc, 'Supplemental References', style='Heading 1')
    W.render(doc, [('refs', refs, 'S')], order)
    out = OUT / 'nh3_supplement_v7.docx'
